Graphics[Table[{cols[[i]], Disk[{i, 0}]}, {i, 5}]]
DominantColors[img, 3, {"Color", "Coverage"}]

hdr = Import["scene.exr"];
ColorToneMapping[hdr, 0.8, Method -> "Drago"]
ColorBalance[photo] (* auto white balance *)

cutout = SetAlphaChannel[img, Binarize[img, 0.9] // ColorNegate];
Export["cutout.png", cutout]
RemoveAlphaChannel[cutout, Black]

cells = MorphologicalComponents[Binarize[img]];
ImageRecolor[img, Image[cells, "Bit"] -> Red]
ImageRecolor[gray, {Binarize[gray, 0.3] -> Blue, ColorNegate[Binarize[gray, 0.7]] -> Orange}]

If[ImageColorSpace[img] =!= "Grayscale", img = ColorConvert[img, "Grayscale"]]
lab = ImageData[ColorConvert[img, "LAB"]];
RandomColor[5]

