rectified = ImagePerspectiveTransformation[photo, tf, {800, 600}]
ImageForwardTransformation[img, {#[[1]] + 0.1 Sin[10 #[[2]]], #[[2]]} &]

edges = EdgeDetect[img];
lines = ImageLines[edges, 0.3, 0.05];
HighlightImage[img, {Thick, Red, Line /@ lines}]
corners = ImageCorners[img, 2, 0.02, 3]; HighlightImage[img, corners]

phantom = ExampleData[{"TestImage", "Lena"}] // ColorConvert[#, "Grayscale"] & // ImageResize[#, 128] &;
sino = Radon[phantom, {180, 128}];
rec = InverseRadon[sino, {128, 128}];
ImageDistance[phantom, rec]

flat = ImageSubtract[micro, EstimatedBackground[micro, 40]];
cells = MorphologicalComponents[Binarize[flat]];
ContourDetect[ColorConvert[img, "Grayscale"], 0.5]

