clean = DeleteBorderComponents[DeleteSmallComponents[comps, 50]];
big = SelectComponents[clean, #Area > 500 && #Elongation < 0.5 &];
Colorize[big]

seg = ImageSegmentationComponents[street];
HighlightImage[street, Colorize[seg]]
fg = ChanVeseBinarize[cellImage];
ComponentMeasurements[fg, "Area"]

bw = Binarize[img];
MorphologicalEulerNumber[bw] (* e.g. 12 objects, 3 holes -> 9 *)
stats = ComponentMeasurements[MorphologicalComponents[bw], {"Area", "Circularity", "Centroid"}, #Area > 30 &, "Dataset"]

